<?php
declare(strict_types=1);
namespace App\Application\Catalog\Service;
use App\Application\Catalog\DTO\Request\CreateSyllabusRequestDto; use App\Application\Catalog\DTO\Response\SyllabusResponseDto; use App\Application\Catalog\Mapper\SyllabusResponseMapper; use App\Application\Catalog\Port\TransactionManagerInterface; use App\Domain\Catalog\Entity\Syllabus; use App\Domain\Catalog\Repository\PositionRepositoryInterface; use App\Domain\Catalog\Repository\SyllabusRepositoryInterface;
final class CreateSyllabusService { public function __construct(private readonly PositionRepositoryInterface $positions,private readonly SyllabusRepositoryInterface $syllabi,private readonly SyllabusResponseMapper $mapper,private readonly TransactionManagerInterface $transactions){} public function create(CreateSyllabusRequestDto $r):SyllabusResponseDto{$name=trim($r->name);if($name===''||mb_strlen($name)>190||($r->sourceUrl!==null&&filter_var($r->sourceUrl,FILTER_VALIDATE_URL)===false))throw new \InvalidArgumentException('Dados do edital invalidos.');$s=new Syllabus($this->uuid(),$r->positionId,$name,$r->publishedAt,$r->sourceUrl);$this->transactions->transactional(fn()=>$this->syllabi->save($s));return $this->mapper->map($s);}private function uuid():string{$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
